INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('de-blocked-account-monthly', 'DE', 'proof_of_funds', 'living', 'Blocked account requirement per month (student visa)', 992, NULL, 'EUR', 'month', 'German national student visa applied for in Pakistan, applications from 1 Jan 2025 (still current on page, 2026)', 'German Embassy Islamabad / Federal Foreign Office (pakistan.diplo.de)', 'https://pakistan.diplo.de/pk-en/service/1995528-1995528', 'From 1 January 2025 the presumed annual requirement that must be paid into the blocked account when applying for a visa will increase to 992,00 Euros monthly or 11.904,00 Euros yearly.', 'VERIFIED', '2026-10-25', '["blocked account (Sperrkonto)","deed of obligation (Verpflichtungserklaerung, sections 66-68 Residence Act) by a sponsor in Germany","German or foreign official scholarship (from Pakistan only HEC scholarships accepted)"]', 'Same page: ''only a scholarship awarded by HEC can be accepted''; embassy may request a blocked amount for up to two years. Federal Foreign Office says the amount follows BAfoeG maximum rates. DAAD also states 992/month ''as of 1 January 2025'' and lists proof of parental income, but the Pakistan mission does not list parental income. Page served from Firecrawl cache dated 2026-10-25.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('de-blocked-account-yearly', 'DE', 'proof_of_funds', 'living', 'Blocked account requirement per year (student visa)', 11904, NULL, 'EUR', 'year', 'German national student visa applied for in Pakistan, applications from 1 Jan 2025 (still current on page, 2026)', 'German Embassy Islamabad / Federal Foreign Office (pakistan.diplo.de)', 'https://pakistan.diplo.de/pk-en/service/1995528-1995528', 'From 1 January 2025 the presumed annual requirement that must be paid into the blocked account when applying for a visa will increase to 992,00 Euros monthly or 11.904,00 Euros yearly.', 'VERIFIED', '2026-10-25', '["blocked account (Sperrkonto)","deed of obligation (Verpflichtungserklaerung)","official scholarship (HEC only among Pakistani awards)"]', 'Use this as the planner figure. Conflicts with the older mission checklist PDF (11,208 EUR) - see de-blocked-account-leaflet-old. Bank fees for the blocked account come on top (Federal Foreign Office).');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('de-blocked-account-leaflet-old', 'DE', 'proof_of_funds', 'living', 'Blocked account amount in mission student checklist PDF (outdated)', 11208, NULL, 'EUR', 'year', 'German Mission Pakistan student visa checklist PDF (undated, pre-2025 figure)', 'German Embassy Islamabad (pakistan.diplo.de)', 'https://pakistan.diplo.de/blob/2208710/4a44b499964d27c04ecb6e5770fdb824/study-visa---leaflet-data.pdf', 'Proof of sufficient financial means for living expenses ☐ blocked account (11,208 EUR for one year) ☐ official obligation letter issued by an Alien’s authority in Germany („Verpflichtungserklärung“) ☐ scholarship award', 'NEEDS_REVIEW', '2026-10-25', '["blocked account","Verpflichtungserklaerung","scholarship award"]', 'Conflicts with the mission''s finance page (11,904 EUR for applications from 1 Jan 2025). Do not use for planning; keep only to explain the discrepancy students may see.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('de-blocked-account-signature-attestation', 'DE', 'cost', 'documents', 'Embassy attestation of blocked-account signature', 25, NULL, 'EUR', 'once', 'Pakistani applicants opening a blocked account (signature attested at Islamabad, Karachi or Lahore)', 'German Embassy Islamabad (pakistan.diplo.de)', 'https://pakistan.diplo.de/pk-en/service/1995528-1995528', 'The fee to be paid directly at the Embassy is 25,- € (about 5400 PKR), but may change due to exchange rate. Please bring the exact amount.', 'VERIFIED', '2026-10-25', NULL, 'PKR equivalent (about 5,400) is the embassy''s own approximation and changes with the exchange rate.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('de-national-visa-fee', 'DE', 'cost', 'visa', 'German national (D) visa fee', 75, NULL, 'EUR', 'once', 'National visa category D (incl. student visa), current law', 'Federal Ministry of Justice - Aufenthaltsverordnung section 46 (gesetze-im-internet.de)', 'https://www.gesetze-im-internet.de/aufenthv/__46.html', 'Die Gebührenhöhe beträgt 1. für die Erteilung eines nationalen Visums (Kategorie „D“), auch für mehrmalige Einreisen 75 Euro,', 'VERIFIED', '2026-10-25', NULL, 'German mission Pakistan student checklist also says ''Visa Fee - in the amount of 75 EUR, to be paid in PKR''. Extension of a D visa: 25 EUR (same section).');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('de-residence-permit-fee', 'DE', 'cost', 'residence_permit', 'Residence permit first issue fee', 100, NULL, 'EUR', 'once', 'First Aufenthaltserlaubnis (any validity), current law', 'Federal Ministry of Justice - Aufenthaltsverordnung section 45 (gesetze-im-internet.de)', 'https://www.gesetze-im-internet.de/aufenthv/__45.html', 'für die Erteilung einer Aufenthaltserlaubnis, einer Blauen Karte EU oder einer ICT-Karte a) mit einer Geltungsdauer von bis zu einem Jahr 100 Euro, b) mit einer Geltungsdauer von mehr als einem Jahr 100 Euro,', 'VERIFIED', '2026-10-25', NULL, 'Statutory maximum; local foreigners authorities may apply reductions/exemptions (e.g. some scholarship holders) under other AufenthV sections - not checked.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('de-residence-permit-extension-fee', 'DE', 'cost', 'residence_permit', 'Residence permit extension fee (more than 3 months)', 93, NULL, 'EUR', 'once', 'Extension of Aufenthaltserlaubnis for a further stay of more than three months, current law', 'Federal Ministry of Justice - Aufenthaltsverordnung section 45 (gesetze-im-internet.de)', 'https://www.gesetze-im-internet.de/aufenthv/__45.html', 'für die Verlängerung einer Aufenthaltserlaubnis, einer Blauen Karte EU oder einer ICT-Karte a) für einen weiteren Aufenthalt von bis zu drei Monaten 96 Euro, b) für einen weiteren Aufenthalt von mehr als drei Monaten 93 Euro,', 'VERIFIED', '2026-10-25', NULL, 'Each extension. Extension of up to 3 months: 96 EUR.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('de-daad-living-range', 'DE', 'cost', 'living', 'DAAD living cost range', 900, 1200, 'EUR', 'month', 'International students in Germany, current DAAD guidance', 'DAAD', 'https://www.daad.de/en/studying-in-germany/living-in-germany/finances/', 'Depending on where in Germany you wish to study, you will need between 900 and 1,200 Euros per month.', 'OFFICIAL_ESTIMATE', '2026-10-25', NULL, 'Includes rent, food, insurance, transport etc.; semester contribution extra. Page served from Firecrawl cache dated 2026-10-25.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('de-daad-average-expenses', 'DE', 'cost', 'living', 'DAAD average monthly student expenses (2023 social survey)', 876, NULL, 'EUR', 'month', 'Average student in Germany, DZHW 22nd Social Survey 2023', 'DAAD (citing DZHW)', 'https://www.daad.de/en/studying-in-germany/living-in-germany/finances/', 'According to the latest social survey from 2023, students have expenses totalling an average of 876 euros per month.', 'OFFICIAL_ESTIMATE', '2026-10-25', NULL, 'Survey year 2023 - older data; prefer the 900-1,200 range or the 992 visa figure for planning.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('de-daad-average-rent', 'DE', 'cost', 'accommodation', 'Average student rent incl. utilities (DAAD/DZHW)', 410, NULL, 'EUR', 'month', 'Average German student, DZHW 22nd Social Survey 2023', 'DAAD (citing DZHW)', 'https://www.daad.de/en/studying-in-germany/living-in-germany/finances/', 'Average expenses of a German student - Rent (including utility costs): EUR 410', 'OFFICIAL_ESTIMATE', '2026-10-25', NULL, '2023 survey data; big-city rents are higher.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('de-health-insurance-statutory-student', 'DE', 'cost', 'insurance', 'Statutory health insurance student rate (under 30)', 120, 130, 'EUR', 'month', 'Students under 30 in statutory health insurance, current DAAD guidance', 'DAAD', 'https://www.daad.de/en/studying-in-germany/living-in-germany/health-insurance/', 'If you are under 30 years of age, you will profit from a reduced student rate of about 120-130 euros per month, which is offered by statutory health insurance providers.', 'OFFICIAL_ESTIMATE', '2026-10-25', NULL, 'From age 30 the standard (higher) contribution applies. Exact insurer tariff not fetched (see gaps). Page served from Firecrawl cache dated 2026-10-25.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('de-semester-contribution-range', 'DE', 'cost', 'semester_fee', 'Semester contribution range (all universities)', 70, 430, 'EUR', 'semester', 'All German higher education institutions, current DAAD guidance', 'DAAD', 'https://www.daad.de/en/studying-in-germany/living-in-germany/finances/', 'The semester contribution varies between higher education institutions and comes to between 70 and 430 EUR. It has to be paid when you enroll and before the start of every new semester.', 'OFFICIAL_ESTIMATE', '2026-10-25', NULL, 'Often includes a semester ticket. DAAD example: University of Cologne WS 2024/25 total EUR 304.25 (older period).');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('de-bw-nonEU-tuition-daad', 'DE', 'cost', 'tuition', 'Baden-Wuerttemberg non-EU tuition (DAAD statement)', 1500, NULL, 'EUR', 'semester', 'Non-EU students in Bachelor''s/Master''s at Baden-Wuerttemberg state universities (not doctoral)', 'DAAD', 'https://www.daad.de/en/studying-in-germany/living-in-germany/finances/', 'The Federal State of Baden-Württemberg charges non-EU citizens tuition fees of EUR 1,500 per semester for (Bachelor''s, Master''s, Diplom and state examination) degree programmes. These fees do not apply to doctoral students.', 'VERIFIED', '2026-10-25', NULL, 'Confirmed by University of Stuttgart page (de-stuttgart-nonEU-tuition). DAAD also notes Bavarian universities may charge non-EU fees of several thousand euros.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('de-stuttgart-nonEU-tuition', 'DE', 'cost', 'tuition', 'University of Stuttgart non-EU tuition fee', 1500, NULL, 'EUR', 'semester', 'Non-EU/EEA students at University of Stuttgart, Bachelor''s/consecutive Master''s, current', 'University of Stuttgart', 'https://www.student.uni-stuttgart.de/en/organizing-studies/formalities/tuition-and-fees/', 'The Land Baden-Württemberg has introduced tuition fees for a second degree (650 EUR / semester) and for international students who are not citizens of an EU/EEA country (1500 EUR / semester).', 'VERIFIED', '2026-10-25', NULL, 'Paid on top of the semester fee (EUR 184). Page served from Firecrawl cache dated 2026-10-25.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('de-stuttgart-semester-fee', 'DE', 'cost', 'semester_fee', 'University of Stuttgart semester fee', 184, NULL, 'EUR', 'semester', 'Students at University of Stuttgart, current (''currently'')', 'University of Stuttgart', 'https://www.student.uni-stuttgart.de/en/organizing-studies/formalities/tuition-and-fees/', 'The semester fee comprises the Administrative fee, the Student Services fee and the Student Council fee. … Currently it amounts to EUR 184.00 for students and EUR 177.50 for doctoral students.', 'VERIFIED', '2026-10-25', NULL, 'Breakdown: administrative fee 80.00, Student Services fee 96.50, student body fee 7.50. No semester ticket included in this figure.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('de-tum-tuition-bachelor', 'DE', 'cost', 'tuition', 'TUM non-EU tuition, Bachelor''s', 2000, 3000, 'EUR', 'semester', 'Non-EU/EEA students newly enrolling at TUM in Bachelor''s programmes, until WS 2026/27 intake', 'Technical University of Munich (TUM)', 'https://www.tum.de/en/studies/fees/tuition', 'Bachelor''s degree programs: usually 2,000 or 3,000 euros per semester', 'VERIFIED', '2026-10-25', NULL, 'Fee band; exact amount on each programme page (''usually''). Semester fee extra. TUM scholarship: one-time grant 500-1,800 EUR per semester. Page modified 2026-10-07; served from Firecrawl cache dated 2026-10-24.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('de-tum-tuition-master', 'DE', 'cost', 'tuition', 'TUM non-EU tuition, Master''s', 4000, 6000, 'EUR', 'semester', 'Non-EU/EEA students newly enrolling at TUM in Master''s programmes, until WS 2026/27 intake', 'Technical University of Munich (TUM)', 'https://www.tum.de/en/studies/fees/tuition', 'Master''s degree programs: usually 4,000 or 6,000 euros per semester', 'VERIFIED', '2026-10-25', NULL, 'Fee band; exact amount per programme. Master''s after a TUM or German Bachelor''s is exempt if proof is given by the enrolment deadline.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('de-tum-tuition-bachelor-2027', 'DE', 'cost', 'tuition', 'TUM non-EU tuition from WS 2027/28, Bachelor''s', 2300, 3400, 'EUR', 'semester', 'Non-EU/EEA students starting at TUM from winter semester 2027/28, Bachelor''s', 'Technical University of Munich (TUM)', 'https://www.tum.de/en/studies/fees', 'Tuition fees for international students from non-EU/EEA countries at TUM will increase for the winter semester 2027/28. The tuition fees will then be - for Bachelor''s programs: 2,300 euros or 3,400 euros', 'VERIFIED', '2026-10-25', NULL, 'Students already enrolled keep the rates in effect at the start of their studies. Page modified 2026-10-22.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('de-tum-tuition-master-2027', 'DE', 'cost', 'tuition', 'TUM non-EU tuition from WS 2027/28, Master''s', 4600, 6800, 'EUR', 'semester', 'Non-EU/EEA students starting at TUM from winter semester 2027/28, Master''s', 'Technical University of Munich (TUM)', 'https://www.tum.de/en/studies/fees', 'The tuition fees will then be - for Bachelor''s programs: 2,300 euros or 3,400 euros - for Master’s programs: 4,600 or 6,800 euros', 'VERIFIED', '2026-10-25', NULL, 'Applies to new enrolments from WS 2027/28.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('de-tum-semester-fee', 'DE', 'cost', 'semester_fee', 'TUM semester fee (Munich, Garching, Weihenstephan)', 97, NULL, 'EUR', 'semester', 'TUM summer semester 2026 (Munich/Garching/Weihenstephan/Heilbronn; Straubing 82 EUR)', 'Technical University of Munich (TUM)', 'https://www.tum.de/en/studies/fees', 'In the summer semester 2026, the semester fee amounts to - 97.00 Euro in Munich, Garching and Weihenstephan - 82.00 Euro in Straubing - 97.00 Euro in Heilbronn', 'NEEDS_REVIEW', '2026-10-25', NULL, 'Past period (SS 2026); WS 2026/27 figure not shown on the page. No full semester ticket included (Deutschlandticket discount purchasable).');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('de-tum-living-munich', 'DE', 'cost', 'living', 'TUM living cost estimate, greater Munich', 1300, 2000, 'EUR', 'month', 'Single-person household in greater Munich area, current TUM guidance', 'Technical University of Munich (TUM)', 'https://www.tum.de/en/studies/fees', 'In the greater Munich area, you should expect monthly living expenses of approximately 1,300 to 2,000 euros (for a single-person household).', 'OFFICIAL_ESTIMATE', '2026-10-25', NULL, 'Straubing and Heilbronn: approx. 900-1,200 EUR/month (same page). Shows Munich students need well above the 992 EUR visa minimum.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('de-rwth-semester-contribution', 'DE', 'cost', 'semester_fee', 'RWTH Aachen semester contribution (average)', 300, NULL, 'EUR', 'semester', 'All RWTH students incl. internationals; no tuition fees (except RWTH Academy programmes)', 'RWTH Aachen University International Office', 'https://www.rwth-aachen.de/cms/root/studium/im-studium/internationales/~inno/faq/?lidx=1', 'There are no tuition fees at RWTH Aachen, with the exception of the programs from RWTH Academy. … The exact amount varies each year, but on average it is about 300 Euros per semester.', 'OFFICIAL_ESTIMATE', '2026-10-25', NULL, 'Includes semester ticket. Exact WS 2026/27 amount is only shown in RWTHonline (gap).');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('de-rwth-living-minimum', 'DE', 'cost', 'living', 'RWTH Aachen minimum living budget', 1100, NULL, 'EUR', 'month', 'Students in Aachen, RWTH costs page (Costs of Studying in Aachen 2026)', 'RWTH Aachen University', 'https://www.rwth-aachen.de/cms/root/studium/vor-dem-studium/internationale-studieninteressierte/organisation-des-studienaufenthaltes/internationale-studierende/~bqmo/kosten/?lidx=1', 'You should budget at least 1,100 euros per month for living expenses when studying at RWTH Aachen University:', 'OFFICIAL_ESTIMATE', '2026-10-25', NULL, 'Same page: Aachen immigration office requires proof of 992 EUR/month income for residence-permit extension. The page''s date for the 11,904 EUR rule (''January 1, 2023'') conflicts with the mission (1 Jan 2025) - not used.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('de-rwth-accommodation', 'DE', 'cost', 'accommodation', 'Aachen accommodation estimate (RWTH)', 400, 600, 'EUR', 'month', 'Students in Aachen, RWTH costs page 2026', 'RWTH Aachen University', 'https://www.rwth-aachen.de/cms/root/studium/vor-dem-studium/internationale-studieninteressierte/organisation-des-studienaufenthaltes/internationale-studierende/~bqmo/kosten/?lidx=1', 'Monthly Expenditure Minimum Costs per Month Accommodation and associated costs between 400 and 600 euros', 'OFFICIAL_ESTIMATE', '2026-10-25', NULL, 'Food 200-300 EUR/month on same table.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('de-rwth-health-insurance', 'DE', 'cost', 'insurance', 'Health insurance estimate (RWTH)', 100, 150, 'EUR', 'month', 'Students in Aachen, RWTH costs page 2026', 'RWTH Aachen University', 'https://www.rwth-aachen.de/cms/root/studium/vor-dem-studium/internationale-studieninteressierte/organisation-des-studienaufenthaltes/internationale-studierende/~bqmo/kosten/?lidx=1', 'Health insurance between 100 and 150 euros', 'OFFICIAL_ESTIMATE', '2026-10-25', NULL, 'Consistent with DAAD''s 120-130 EUR statutory student rate.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('de-stwm-dorm-average-rent', 'DE', 'cost', 'accommodation', 'Studierendenwerk Muenchen Oberbayern average dorm rent', 400.6, NULL, 'EUR', 'month', 'Single place in Studierendenwerk Muenchen Oberbayern halls (Munich, Freising, Rosenheim), current', 'Studierendenwerk Muenchen Oberbayern', 'https://www.studierendenwerk-muenchen-oberbayern.de/wohnheime/', 'Die monatliche Miete für einen Einzelwohnplatz liegt im Durchschnitt bei rund 400,60 Euro.', 'OFFICIAL_ESTIMATE', '2026-10-25', NULL, 'Average, warm rent incl. operating costs. Waiting time 1 to 7 semesters. Per-hall price list PDF (Wartezeiten_Mietpreisliste_deutsch.pdf) not fetched - see gaps.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('it-subsistence-means-year', 'IT', 'proof_of_funds', 'living', 'Means of subsistence for study visa (per year)', 10179.85, NULL, 'EUR', 'year', 'Italian study visa (D) - university enrolment, applicants resident in Pakistan, checklist ME10 (June 2026), a.y. 2026/27', 'Embassy of Italy Islamabad (MAECI)', 'https://ambislamabad.esteri.it/wp-content/uploads/2026/06/ME10_Study-visa-D.pdf', 'Subsistence funds held in a bank account in the student’s name must amount to at least EUR 10,179.85 per year (as provided by the Ministry of the Interior Directive of 1 March 2000).', 'VERIFIED', '2026-10-25', '["bank account in the student''s name","applicant''s and parents'' (or relatives up to 4th degree) financial means, with tax returns, payslips and 6 months of signed bank statements","scholarship from reputable Italian institutions or foreign entities considered reliable by the Embassy","sponsor affidavit stating amount, origin and duration (apostilled, translated into Italian)"]', 'Planner figure for Pakistan. Embassy states: cash, guarantees from persons outside the family unit, bank guarantees or surety bonds are NOT acceptable; one-off deposits are not judged alone. Only a yearly figure is stated (no monthly figure given by Islamabad). Cached copy dated 2026-10-25.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('it-subsistence-means-oslo-conflict', 'IT', 'proof_of_funds', 'living', 'Means of subsistence quoted by Italian Embassy Oslo (conflicting)', 6947.33, NULL, 'EUR', 'year', 'Italian study visa at Embassy of Italy Oslo (not Pakistan)', 'Embassy of Italy Oslo (MAECI)', 'https://amboslo.esteri.it/en/servizi-consolari-e-visti/servizi-per-il-cittadino-straniero/visti/', 'Proof that the applicant has sufficient means of subsistence of no less than 534.41 euros per month, equal to 6,947.33 euros per year (13 monthly payments).', 'NEEDS_REVIEW', '2026-10-25', '["personal or financial resources","economic guarantees by Italian institutions, local governments or reliable foreign institutions"]', 'Conflicts with Islamabad (10,179.85 EUR/year). Use Islamabad for Pakistani applicants; this item only documents the discrepancy (534.41 EUR/month x 13).');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('it-visa-fee-study', 'IT', 'cost', 'visa', 'Italian national study visa consular fee', 50, NULL, 'EUR', 'once', 'National visa for study purposes (type D), MAECI consular fee table, Q4 2026', 'Consulate General of Italy Los Angeles (MAECI consular fee table)', 'https://conslosangeles.esteri.it/it/servizi-consolari-e-visti/servizi-per-il-cittadino-italiano/altri-servizi/albo-consolare/estratto-tabella-diritti-consolari/', 'Visto Nazionale per soggiorni lunga durata (tipo D) 116.00 $133.60 Visto Nazionale per motivi di studio 50.00 $57.60', 'VERIFIED', '2026-10-25', NULL, 'Euro fee is set by the national consular fee table (same worldwide); local-currency amount and the PKR figure at Islamabad not fetched. BLS-Intiana (Embassy''s outsourced centre) service fee is extra - gap. Do not use the general type D fee (116 EUR) for students.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('it-permesso-stamp-duty', 'IT', 'cost', 'residence_permit', 'Permesso di soggiorno - revenue stamp (marca da bollo)', 16, NULL, 'EUR', 'once', 'Each permesso di soggiorno application/renewal via postal kit', 'Portale Immigrazione (Ministry of the Interior / Poste Italiane)', 'https://www.portaleimmigrazione.it/ITA/tabelleCosti.html', 'Marca da bollo 16.00 € Da acquistare in tabaccheria o dove si vendono valori bollati', 'VERIFIED', '2026-10-25', NULL, 'Table dated 22/07/2024 on page; Polizia di Stato kit PDF also lists ''marca da bollo da € 16,00''.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('it-permesso-card-production', 'IT', 'cost', 'residence_permit', 'Permesso di soggiorno - electronic card production', 30.46, NULL, 'EUR', 'once', 'Each permesso di soggiorno issue/renewal', 'Portale Immigrazione (Ministry of the Interior / Poste Italiane)', 'https://www.portaleimmigrazione.it/ITA/tabelleCosti.html', 'Produzione del Permesso di Soggiorno 30.46 € Da versare sul conto corrente postale n. 67422402 del Ministero dell''Economia e delle Finanze', 'VERIFIED', '2026-10-25', NULL, 'Paid in one postal slip together with the contribution (40 EUR for study permits up to 1 year = 70.46 EUR slip).');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('it-permesso-contribution-study', 'IT', 'cost', 'residence_permit', 'Permesso di soggiorno - contribution (study, up to 1 year)', 40, NULL, 'EUR', 'once', 'Study permesso (visa from abroad, stay over 3 months), validity up to 1 year', 'Polizia di Stato - Questura (kit postale document list)', 'https://questure.poliziadistato.it/statics/05/documenti_per_rilascio_permessi_di_soggiorno_da_richiedere_con_kit_postale.pdf?lang=it', 'STUDIO (con visto dall’estero), solo per periodi superiori ai 3 mesi. … bollettino postale per la smart card (€ 30,46) e per il contributo previsto (€ 40,00 per permessi di soggiorno di durata inferiore o pari 1 anno).', 'VERIFIED', '2026-10-25', NULL, 'Portale Immigrazione: 50 EUR for permits of more than 1 and up to 2 years. Questura PDF is from a provincial Questura (Rovigo references); fees are national. Cached copy dated 2026-10-23.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('it-permesso-postal-service', 'IT', 'cost', 'residence_permit', 'Permesso di soggiorno - Poste Italiane kit shipping fee', 30, NULL, 'EUR', 'once', 'Each postal-kit application at a Sportello Amico post office', 'Portale Immigrazione (Ministry of the Interior / Poste Italiane)', 'https://www.portaleimmigrazione.it/ITA/tabelleCosti.html', 'Costo spedizione Poste Italiane 30.00 € Da pagare al momento dell''accettazione dell''istanza in UP', 'VERIFIED', '2026-10-25', NULL, 'Total first study permesso (up to 1 year) = 16 + 30.46 + 40 + 30 = 116.46 EUR. The page''s worked examples contain arithmetic typos (''30.36€ + 40.00€ = 70.46€''); table rows used instead.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('it-visa-health-insurance-requirement', 'IT', 'proof_of_funds', 'insurance', 'Health insurance required for study visa (minimum coverage)', NULL, NULL, 'EUR', 'once', 'Italian study visa (D) applied for in Islamabad, 2026', 'Embassy of Italy Islamabad (MAECI)', 'https://ambislamabad.esteri.it/wp-content/uploads/2026/06/ME10_Study-visa-D.pdf', 'Health insurance with minimum coverage of EUR 30,000 for emergency hospital treatment and repatriation expenses, valid throughout the Schengen Area.', 'VERIFIED', '2026-10-25', '["health insurance policy (min. EUR 30,000 coverage)"]', 'Requirement only - premium cost not stated. EUR 30,000 is coverage, NOT a cost; amount left null on purpose.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('it-polimi-first-instalment', 'IT', 'cost', 'tuition', 'Politecnico di Milano first fee instalment', 880.04, NULL, 'EUR', 'once', 'New students enrolling in Bachelor''s/Master''s/single-cycle at PoliMi, a.y. 2026/27', 'Politecnico di Milano', 'https://www.polimi.it/en/prospective-students/how-much-does-it-cost/laurea-laurea-magistrale-and-single-cycle-programmes', 'you will need to pay the first instalment of €880.04 upon enrolment.', 'VERIFIED', '2026-10-25', NULL, 'Part of the annual fee (not additional to the 3,943.04 maximum). Reducible with an ISEE below 27,740 EUR. Cached copy dated 2026-10-24.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('it-polimi-annual-fee-max', 'IT', 'cost', 'tuition', 'Politecnico di Milano annual fee (maximum; non-EU Master''s)', 3943.04, NULL, 'EUR', 'year', 'PoliMi a.y. 2026/27, standard plan 46-74 ECTS; maximum charged to non-EU reserved-category Master''s students with a foreign first degree and no scholarship', 'Politecnico di Milano', 'https://www.polimi.it/en/prospective-students/how-much-does-it-cost/laurea-laurea-magistrale-and-single-cycle-programmes', 'For a standard study plan of between 46 and 74 ECTS and an ISEE of up to € 22,000, the amount is € 157.04; for a higher-value ISEE, the amount gradually increases up to a maximum of € 3,943.04.', 'VERIFIED', '2026-10-25', NULL, 'Fee band 157.04 (ISEE up to 22,000) to 3,943.04. Pakistani Master''s applicants with a Pakistani Bachelor''s pay the maximum pro-rated by ECTS ''even if they submit the ISEE/ISEEU parificato''. Bachelor''s fees follow the ISEE parificato bands.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('it-padova-fixed-fee-group-a', 'IT', 'cost', 'tuition', 'University of Padova fixed fee, non-EU, Group A (humanities)', 2790, NULL, 'EUR', 'year', 'Non-EU students with household outside Italy, enrolled from 2023/24, Group A programmes, a.y. 2026/27', 'University of Padova (Call for student fees and exemptions 2026/27)', 'https://wwwassets.unipd.it/sites/default/files/2026-07/1.Bando%20ContribuzioneEsoneri%202026-27_ENG.pdf', 'Table 4: Fixed fee applied to international students with non-EU citizenship … Group A € 2,790.00 € 930.00', 'VERIFIED', '2026-10-25', NULL, 'Column 1 = ''Total fixed amount for students with non-EU citizenship and household not residing in Italy''; 930 EUR column is for ''particularly poor countries'' (DM 166/2025) - Pakistan''s status on that decree not verified (Pakistan is NOT on Unibo''s DM 176/2026 poor-country list). Unclear whether the fixed amount includes the 208 EUR regional fee + stamp duty - do not add automatically. 100 full fee waivers exist for English-taught programmes.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('it-padova-fixed-fee-group-b', 'IT', 'cost', 'tuition', 'University of Padova fixed fee, non-EU, Group B (science/engineering/medicine)', 2990, NULL, 'EUR', 'year', 'Non-EU students with household outside Italy, enrolled from 2023/24, Group B programmes (Engineering, Science, Medicine etc.), a.y. 2026/27', 'University of Padova (Call for student fees and exemptions 2026/27)', 'https://wwwassets.unipd.it/sites/default/files/2026-07/1.Bando%20ContribuzioneEsoneri%202026-27_ENG.pdf', 'Group of the degree programme Total fixed amount for students with non-EU citizenship and household not residing in Italy … Group B € 2,990.00 € 996.66', 'VERIFIED', '2026-10-25', NULL, '996.66 EUR = poor-country (DAC list) rate; see notes on group A item. Non-recalculable (ISEE parificato only reduces the regional fee).');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('it-padova-first-instalment', 'IT', 'cost', 'tuition', 'University of Padova first instalment (regional fee + stamp duty)', 208, NULL, 'EUR', 'once', 'First-year enrolment at Padova, a.y. 2026/27', 'University of Padova (Call for student fees and exemptions 2026/27)', 'https://wwwassets.unipd.it/sites/default/files/2026-07/1.Bando%20ContribuzioneEsoneri%202026-27_ENG.pdf', 'a) € 208.00 for those who enrol in the first year of the degree programmes, consisting of: - € 192.00: regional fee for the right to university education; -€ 16.00: stamp duty.', 'VERIFIED', '2026-10-25', NULL, 'May overlap with the fixed amount (Table 1 shows maximum totals as all-inclusive fee + 208). Flag for review before summing.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('it-unibo-flat-fee-first-cycle', 'IT', 'cost', 'tuition', 'University of Bologna reduced fixed fee, non-OECD, Bachelor''s/single-cycle', 1157.04, NULL, 'EUR', 'year', 'Nationals of non-OECD countries (Pakistan listed), freshmen or with minimum credits, first- or single-cycle, family income/assets only abroad, a.y. 2026/27', 'University of Bologna', 'https://www.unibo.it/en/study/enrolment-fees-and-other-procedures/degree-programmes/tuition-fees-and-exemptions/reduced-fixed-fee-for-citizens-of-particularly-poor-and-developing-countries-or-non-eu-non-oecd-countries', 'If you are a freshman or have the minimum number of credits € 1,000 + €157.04 € 1,200 + €157.04 Reduced fixed fee for nationals of non-OECD countries', 'VERIFIED', '2026-10-25', NULL, '1,000 + 157.04 (first instalment: regional tax 140 + stamp 16 + insurance 1.04). In the scraped markdown each table''s caption follows the table; the 500/600 table is for ''particularly poor'' countries. Pakistan appears on Unibo''s 2026 non-OECD list PDF and not on the poor-country list (both scraped). Without the declaration the maximum fee applies.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('it-unibo-flat-fee-second-cycle', 'IT', 'cost', 'tuition', 'University of Bologna reduced fixed fee, non-OECD, Master''s', 1357.04, NULL, 'EUR', 'year', 'Nationals of non-OECD countries (Pakistan listed), freshmen or with minimum credits, second-cycle (Master''s), a.y. 2026/27', 'University of Bologna', 'https://www.unibo.it/en/study/enrolment-fees-and-other-procedures/degree-programmes/tuition-fees-and-exemptions/reduced-fixed-fee-for-citizens-of-particularly-poor-and-developing-countries-or-non-eu-non-oecd-countries', 'If you are a freshman or have the minimum number of credits € 1,000 + €157.04 € 1,200 + €157.04 Reduced fixed fee for nationals of non-OECD countries', 'VERIFIED', '2026-10-25', NULL, '1,200 + 157.04. Without minimum credits: 1,400 + 157.04. See caption-order note on first-cycle item.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('it-polimi-accommodation', 'IT', 'cost', 'accommodation', 'Milan accommodation estimate (PoliMi)', 400, 700, 'EUR', 'month', 'Students in Milan, PoliMi on-arrival guidance (undated, current page)', 'Politecnico di Milano', 'https://www.polimi.it/en/prospective-students/how-to-apply/on-arrival-information/useful-information', 'Accomodation €400 - €700 per month Costs vary depending on the area, the kind of room (single or double) and any programme benefits you may have access to.', 'OFFICIAL_ESTIMATE', '2026-10-25', NULL, 'Page says costs ''are approximate and should be used as a guide only''. Page not dated - may be older. Cached copy dated 2026-10-24.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('it-polimi-food', 'IT', 'cost', 'living', 'Milan food estimate (PoliMi)', 150, 200, 'EUR', 'month', 'Students in Milan, PoliMi on-arrival guidance (undated)', 'Politecnico di Milano', 'https://www.polimi.it/en/prospective-students/how-to-apply/on-arrival-information/useful-information', 'Food €150 - €200 per month', 'OFFICIAL_ESTIMATE', '2026-10-25', NULL, 'Other lines on same page: social life 100-200, travel 20-30 (public transport 22/month), mobile 10-30 EUR/month.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('it-ergo-scholarship-fuori-sede', 'IT', 'cost', 'stipend', 'ER.GO (Emilia-Romagna DSU) scholarship, off-site student - INCOME', 7171.11, NULL, 'EUR', 'year', 'ER.GO regional scholarship (Bologna etc.), ''fuori sede'' student, ISEE up to 16,666.67, a.y. 2026/27', 'ER.GO - Azienda Regionale per il Diritto agli Studi Superiori (Emilia-Romagna)', 'https://www.er-go.it/cosa-fare-per/bandi-di-concorso/importi-pagamenti-e-revoche/importi', 'Anno accademico 2026/2027 INTERVALLI DI VALORE ISEE IMPORTO BORSA: FUORI SEDE … fino a € 16.666,67 € 7.171,11 € 4.190,71 € 2.890,16', 'VERIFIED', '2026-10-25', NULL, 'INCOME, not a cost - planner must subtract, never add. Merit/income-based; not guaranteed. Lower ISEE bands: 4,661.22 / 3,872.40 / 3,585.56. ER.GO winners also get full fee exemption at Unibo (pay only 157.04). Page updated 22-06-2026.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('it-ergo-scholarship-low-isee', 'IT', 'cost', 'stipend', 'ER.GO scholarship, off-site, ISEE up to 12,500 (+15%) - INCOME', 8246.78, NULL, 'EUR', 'year', 'ER.GO regional scholarship, ''fuori sede'', ISEE up to 12,500, a.y. 2026/27', 'ER.GO - Azienda Regionale per il Diritto agli Studi Superiori (Emilia-Romagna)', 'https://www.er-go.it/cosa-fare-per/bandi-di-concorso/importi-pagamenti-e-revoche/importi', 'L''importo della borsa di studio è incrementato del 15% in caso di ISEE fino a € 12.500,00. … fino a € 12.500,00 € 8.246,78 € 4.819,32 € 3.323,68', 'VERIFIED', '2026-10-25', NULL, 'INCOME, not a cost. Amounts include any share converted into meal service. Women in STEM get +20% (8,605.33 top band).');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('cn-x1-visa-fee-pakistan', 'CN', 'cost', 'visa', 'Chinese visa fee (X1) for Pakistani ordinary passport', 0, NULL, 'PKR', 'once', 'All Chinese visa types incl. X1, Pakistani ordinary passport holders applying in Pakistan (page dated 2025-04-28, current)', 'Embassy of the People''s Republic of China in Pakistan', 'https://pk.china-embassy.gov.cn/eng/lsfw/va/202504/t20250428_11606296.htm', 'Holders of diplomatic and official passport from every country (except the United States), as well as ordinary passports from Pakistan, are exempt from paying all types of visa fees.', 'VERIFIED', '2026-10-25', NULL, 'Gerry''s Chinese Visa Application Service Center charges its own service fee ''not associated with Chinese Embassy'' - amount not fetched (gap).');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('cn-csc-stipend-bachelor', 'CN', 'cost', 'stipend', 'CSC scholarship living allowance, Bachelor''s - INCOME', 2500, NULL, 'CNY', 'month', 'Chinese Government Scholarship (full), undergraduate', 'Nanjing Audit University international office (reproducing CSC/Campus China standard)', 'https://lxsy.nau.edu.cn/7231/list.htm', '生活费： 本科生：2,500元人民币/月 硕士研究生和普通进修生：3,000元人民币/月 博士研究生和高级进修生：3,500元人民币/月', 'NEEDS_REVIEW', '2026-10-25', NULL, 'INCOME, not a cost. Page is from an older intake (asks for passport valid after 1 March 2023); not Campus China itself. Same figures appear on many university pages but current-year CSC confirmation not fetched. Full scholarship also covers tuition, dorm (or subsidy) and insurance.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('cn-csc-stipend-master', 'CN', 'cost', 'stipend', 'CSC scholarship living allowance, Master''s - INCOME', 3000, NULL, 'CNY', 'month', 'Chinese Government Scholarship (full), Master''s and general scholars', 'Nanjing Audit University international office (reproducing CSC/Campus China standard)', 'https://lxsy.nau.edu.cn/7231/list.htm', '生活费： 本科生：2,500元人民币/月 硕士研究生和普通进修生：3,000元人民币/月 博士研究生和高级进修生：3,500元人民币/月', 'NEEDS_REVIEW', '2026-10-25', NULL, 'INCOME. See notes on Bachelor''s item (older cycle page).');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('cn-csc-stipend-phd', 'CN', 'cost', 'stipend', 'CSC scholarship living allowance, PhD - INCOME', 3500, NULL, 'CNY', 'month', 'Chinese Government Scholarship (full), doctoral and senior scholars', 'Nanjing Audit University international office (reproducing CSC/Campus China standard)', 'https://lxsy.nau.edu.cn/7231/list.htm', '生活费： 本科生：2,500元人民币/月 硕士研究生和普通进修生：3,000元人民币/月 博士研究生和高级进修生：3,500元人民币/月', 'NEEDS_REVIEW', '2026-10-25', NULL, 'INCOME. Same page: comprehensive medical insurance covered at 800 CNY/person/year.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('cn-medical-insurance', 'CN', 'cost', 'insurance', 'Comprehensive medical insurance (mandatory)', 800, NULL, 'CNY', 'year', 'International degree students at Zhejiang University, 2026 intake (Ministry of Education requirement)', 'Zhejiang University International College', 'https://iczu.zju.edu.cn/admissionsen/2024/1030/c68988a2981659/page.htm', 'Medical Insurance Fee: 800 RMB yuan/academic year According to the regulations of the Ministry of Education, international students must purchase comprehensive medical insurance in the mainland of China', 'VERIFIED', '2026-10-25', NULL, 'SJTU 2026 also states ''Insurance Fee RMB 800 per academic year''. Not registered without it. Cached copy dated 2026-10-25.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('cn-residence-permit-under-1yr', 'CN', 'cost', 'residence_permit', 'Residence permit fee (validity under 1 year)', 400, NULL, 'CNY', 'once', 'Foreigner residence permit, validity less than one year, national fee standard', 'National Immigration Administration of China (NIA)', 'https://www.nia.gov.cn/n741445/n741624/index.html', '外国人居留许可及增加偕行人（不满一年） 元／人．次 400', 'VERIFIED', '2026-10-25', NULL, 'Fee basis: NDRC/MOF Fagai Jiage [2004] 2230. Per person per issue. Cached copy dated 2026-10-24.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('cn-residence-permit-1-3yr', 'CN', 'cost', 'residence_permit', 'Residence permit fee (validity 1 to 3 years)', 800, NULL, 'CNY', 'once', 'Foreigner residence permit, validity one year (inclusive) to three years, national fee standard', 'National Immigration Administration of China (NIA)', 'https://www.nia.gov.cn/n741445/n741624/index.html', '外国人居留许可及增加偕行人［一年（含）至三年］ 元／人．次 800', 'VERIFIED', '2026-10-25', NULL, 'Change of residence permit: 200 CNY per time. Universities typically issue 1-year permits renewed annually (400 CNY) - check per university.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('cn-medical-exam-njust', 'CN', 'cost', 'medical_exam', 'Physical examination fee in China (NJUST estimate)', 538, NULL, 'CNY', 'once', 'NJUST international postgraduates, 2026 intake', 'Nanjing University of Science and Technology (NJUST)', 'https://study.njust.edu.cn/74/79/c4398a357497/page.htm', 'Physical Examination Fee: Approx. CNY 538/examination', 'OFFICIAL_ESTIMATE', '2026-10-25', NULL, 'Same page: ''Visa/Residence permit: At least CNY 400/year''. Pre-departure Foreigner Physical Examination Form (done in Pakistan) cost not stated.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('cn-sjtu-tuition-ug-chinese', 'CN', 'cost', 'tuition', 'SJTU tuition, Chinese-taught Bachelor''s', 24800, NULL, 'CNY', 'year', 'Shanghai Jiao Tong University self-funded undergraduates, Chinese-taught, 2026 intake', 'Shanghai Jiao Tong University International Student Center', 'https://en.sjtu.edu.cn/study-sjtu/prospective/degree-programs/387', '2. Tuition Fee RMB 24,800 per academic year. Note: The tuition fee for the Global Institute of Future Technology is RMB 120,000 per academic year.', 'VERIFIED', '2026-10-25', NULL, 'Application fee RMB 800 non-refundable. Cached copy dated 2026-10-24.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('cn-sjtu-tuition-ug-english', 'CN', 'cost', 'tuition', 'SJTU tuition, English-taught Engineering Cluster Bachelor''s', 120000, NULL, 'CNY', 'year', 'SJTU 2026-27, English Engineering Cluster programmes & Global Institute of Future Technology', 'Shanghai Jiao Tong University International Student Center (Guide for 2026 International Students, July 2026)', 'https://smse.sjtu.edu.cn/storage/global/web/en/article/2026/07/312becd7f5e3729370924d69fe3ed7da.pdf', 'Undergraduate Programs: CNY 24,800 / academic year for Chinese programs, CNY 12,0000 / academic year for English Engineering Cluster programs & Global Institute of Future Technology', 'VERIFIED', '2026-10-25', NULL, 'Source prints ''CNY 12,0000'' (typo); read as 120,000, consistent with the SJTU web page''s ''RMB 120,000'' for Global Institute of Future Technology. Civil Engineering BEng 80,000; French programmes 65,000.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('cn-sjtu-tuition-master', 'CN', 'cost', 'tuition', 'SJTU tuition, general Master''s', 28900, NULL, 'CNY', 'year', 'SJTU 2026-27 general Master''s programmes (specific programmes differ)', 'Shanghai Jiao Tong University International Student Center (Guide for 2026 International Students)', 'https://smse.sjtu.edu.cn/storage/global/web/en/article/2026/07/312becd7f5e3729370924d69fe3ed7da.pdf', 'General Master’ s Programs: CNY 28,900 /year; Doctoral Programs: CNY 45,500 /year. Please note that specific master’s programs charge different tuition fees', 'VERIFIED', '2026-10-25', NULL, 'Doctoral: 45,500 CNY/year (see cn-sjtu-tuition-phd).');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('cn-sjtu-tuition-phd', 'CN', 'cost', 'tuition', 'SJTU tuition, Doctoral', 45500, NULL, 'CNY', 'year', 'SJTU 2026-27 doctoral programmes', 'Shanghai Jiao Tong University International Student Center (Guide for 2026 International Students)', 'https://smse.sjtu.edu.cn/storage/global/web/en/article/2026/07/312becd7f5e3729370924d69fe3ed7da.pdf', 'General Master’ s Programs: CNY 28,900 /year; Doctoral Programs: CNY 45,500 /year.', 'VERIFIED', '2026-10-25', NULL, '');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('cn-sjtu-accommodation', 'CN', 'cost', 'accommodation', 'SJTU on-campus accommodation', 6600, 12600, 'CNY', 'semester', 'SJTU undergraduates (Chinese-taught guide), 2026 intake', 'Shanghai Jiao Tong University International Student Center', 'https://en.sjtu.edu.cn/study-sjtu/prospective/degree-programs/387', '4. Accommodation Fee Ranges from RMB 6,600 to RMB 12,600 per semester. The specific cost depends on the type of dormitory and campus arrangement.', 'VERIFIED', '2026-10-25', NULL, 'Per semester (two semesters per year). Off-campus renting allowed.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('cn-sjtu-application-fee', 'CN', 'cost', 'application', 'SJTU application fee', 800, NULL, 'CNY', 'once', 'SJTU undergraduate and graduate applications, 2026 intake', 'Shanghai Jiao Tong University International Student Center', 'https://en.sjtu.edu.cn/study-sjtu/prospective/degree-programs/387', '1. Application Fee RMB 800. The application fee is non-refundable once paid.', 'VERIFIED', '2026-10-25', NULL, 'Zhejiang University also charges RMB 800 (non-refundable) for 2026 undergraduate applications.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('cn-njust-tuition-master-english', 'CN', 'cost', 'tuition', 'NJUST tuition, English-taught Master''s', 36000, NULL, 'CNY', 'year', 'Nanjing University of Science and Technology international postgraduates, 2026 intake', 'Nanjing University of Science and Technology (NJUST) School of International Education', 'https://study.njust.edu.cn/74/79/c4398a357497/page.htm', 'Master programs in Chinese: CNY 24,000/Year (Approx. USD 3,400/Year) ▪ Master programs in English: CNY 36,000/Year (Approx. USD 5,050/Year)', 'VERIFIED', '2026-10-25', NULL, 'Provincial/ministry (MIIT) university example. Chinese-taught Master''s 24,000; Doctoral Chinese 36,000; Doctoral English 44,200 CNY/year.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('cn-njust-tuition-master-chinese', 'CN', 'cost', 'tuition', 'NJUST tuition, Chinese-taught Master''s', 24000, NULL, 'CNY', 'year', 'NJUST international postgraduates, 2026 intake', 'Nanjing University of Science and Technology (NJUST) School of International Education', 'https://study.njust.edu.cn/74/79/c4398a357497/page.htm', 'Master programs in Chinese: CNY 24,000/Year (Approx. USD 3,400/Year)', 'VERIFIED', '2026-10-25', NULL, '');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('cn-njust-tuition-phd-english', 'CN', 'cost', 'tuition', 'NJUST tuition, English-taught Doctoral', 44200, NULL, 'CNY', 'year', 'NJUST international doctoral students, 2026 intake', 'Nanjing University of Science and Technology (NJUST) School of International Education', 'https://study.njust.edu.cn/74/79/c4398a357497/page.htm', 'Doctoral programs in Chinese: CNY 36,000/Year (Approx. USD 5,050/Year) ▪ Doctoral programs in English: CNY 44,200/Year (Approx. USD 6,200/Year)', 'VERIFIED', '2026-10-25', NULL, '');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('cn-njust-accommodation-master', 'CN', 'cost', 'accommodation', 'NJUST dormitory, Master''s (quad room)', 4000, NULL, 'CNY', 'year', 'NJUST Master''s students, on-campus quad room, 2026 intake', 'Nanjing University of Science and Technology (NJUST) School of International Education', 'https://study.njust.edu.cn/74/79/c4398a357497/page.htm', 'Accommodation Fee: ▪ Master program: CNY 4,000/year (on campus dormitory with a quad room) ▪ Doctoral program: CNY 9,000/year (on campus dormitory with a double room)', 'VERIFIED', '2026-10-25', NULL, 'Doctoral double room 9,000 CNY/year. Electricity approx. 1,000 CNY/year extra.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('cn-njust-meals', 'CN', 'cost', 'living', 'NJUST meal budget estimate', 20000, NULL, 'CNY', 'year', 'NJUST international postgraduates, Nanjing, 2026 intake', 'Nanjing University of Science and Technology (NJUST) School of International Education', 'https://study.njust.edu.cn/74/79/c4398a357497/page.htm', 'Other Estimated Expenses: ▪ Electricity: Approx. CNY 1,000/year ▪ Textbook Fee: Approx. CNY 1,000/year ▪ Meal Budget: Approx. CNY 20,000/year', 'OFFICIAL_ESTIMATE', '2026-10-25', NULL, 'Textbooks approx. 1,000 CNY/year; electricity approx. 1,000 CNY/year.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('cn-njust-application-fee', 'CN', 'cost', 'application', 'NJUST application fee', 500, NULL, 'CNY', 'once', 'NJUST international postgraduate applications, 2026 intake', 'Nanjing University of Science and Technology (NJUST) School of International Education', 'https://study.njust.edu.cn/74/79/c4398a357497/page.htm', 'Application Fee: CNY 500 (Payment in the application system, non-refundable once paid)', 'VERIFIED', '2026-10-25', NULL, '');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('cn-njust-proof-of-funds', 'CN', 'proof_of_funds', 'living', 'Financial statement required (no minimum stated)', NULL, NULL, 'CNY', 'once', 'NJUST international postgraduate application, 2026 intake', 'Nanjing University of Science and Technology (NJUST) School of International Education', 'https://study.njust.edu.cn/74/79/c4398a357497/page.htm', '10. Financial Statement: Proof of sufficient funds (e.g., bank statement, sponsor''s income certificate or guarantee letter).', 'VERIFIED', '2026-10-25', '["bank statement","sponsor''s income certificate","guarantee letter"]', 'Requirement confirmed; no minimum amount stated. A sensible planner proxy is first-year tuition + accommodation + insurance, but that is NOT an official figure.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('pk-hec-degree-attestation', 'PK', 'cost', 'documents', 'HEC degree/transcript attestation (per document)', 3000, NULL, 'PKR', 'once', 'HEC online e-attestation of degree, transcript, provisional certificate or HEC equivalence letter, current', 'Higher Education Commission (HEC) Pakistan', 'https://www.hec.gov.pk/english/services/students/DAS/Pages/Degree-Attestation.aspx', 'The attestation fee is Rs. 3,000 per document (degree, transcript, provisional certificate, or HEC equivalence letter).', 'VERIFIED', '2026-10-25', NULL, 'Per document - multiply by number of documents (e.g. degree + transcript = 6,000). Non-refundable if wrong selection. Needed for Master''s/PhD applicants.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('pk-ibcc-attestation', 'PK', 'cost', 'documents', 'IBCC attestation of SSC/HSSC certificate (per original)', 1200, NULL, 'PKR', 'once', 'IBCC standard attestation (without express service) of original certificate/DMC, current', 'Inter Boards Coordination Commission (IBCC)', 'https://ibcc.edu.pk/faqs/attestation-faqs/', 'What is the fee for obtaining standard IBCC attestation (without express service)? … Original Certificate/DMC Fee: PKR 1200 each', 'VERIFIED', '2026-10-25', NULL, 'Per document. Needed for Bachelor''s applicants (Matric/FSc). Express service costs more (not fetched).');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('pk-ibcc-equivalence-foreign', 'PK', 'cost', 'documents', 'IBCC equivalence certificate, foreign qualification (e.g. O/A Levels)', 6000, NULL, 'PKR', 'once', 'IBCC equivalence of foreign qualifications (O/A Levels, American HSD, IB etc.), current', 'Inter Boards Coordination Commission (IBCC)', 'https://ibcc.edu.pk/faqs/equivalence-faqs/', 'The equivalence fee for foreign qualifications is Rs. 6000 each, while for local qualifications, it is Rs. 4000 each.', 'VERIFIED', '2026-10-25', NULL, 'Per certificate. Urgent O/A Level equivalence: Rs 12,000 each. Only O/A-Level-type students need this before IBCC attestation. Cached copy dated 2026-10-25.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('pk-mofa-apostille-educational', 'PK', 'cost', 'documents', 'MOFA apostille, educational document (per document)', 3000, NULL, 'PKR', 'once', 'Ministry of Foreign Affairs apostille of educational documents, current (fee revised w.e.f. 8 July 2024 per MOFA consular page)', 'Ministry of Foreign Affairs (MOFA) Pakistan - Apostille portal', 'https://apostille.mofa.gov.pk/fee-structure', 'Document Type Amount Personal Document Rs 3,000 Legal Document Rs 4,500 Educational Document Rs 3,000', 'VERIFIED', '2026-10-25', NULL, 'Per document. Italy (Islamabad) requires Pakistani documents to bear an Apostille; also the NADRA FRC. The 8 July 2024 revision date comes from a search snippet of mofa.gov.pk, not scraped.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('de-tk-student-health-2026-under23', 'DE', 'cost', 'insurance', 'TK statutory student health + long-term care insurance, under 23 (no child)', 141.16, NULL, 'EUR', 'month', 'Compulsorily insured students in Germany (statutory student tariff), under 23 without child, valid from 01.01.2026', 'Techniker Krankenkasse (TK), statutory health insurer', 'https://www.tk.de/en/contribution-foreign-students-german-health-insurance-2038022', 'Monthly contributions for students with statutory insurance cover - valid from 01.01.2026 Breakdown of the monthly contribution Health insurance Long-term care insurance* Total amount up to 23 years without child 110.38 EUR 30.78 EUR 141.16 EUR', 'VERIFIED', '2026-10-25', NULL, 'Page dated 04.02.2026. Health part 110.38 EUR (includes TK supplementary rate 2.69%) + long-term care 30.78 EUR. Student rate is based on the BAfoeG requirement rate and applies until age 30 (extensions possible). Other insurers'' student rates differ only by their own supplementary rate.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('de-tk-student-health-2026-23plus', 'DE', 'cost', 'insurance', 'TK statutory student health + long-term care insurance, 23 and over (no child)', 146.29, NULL, 'EUR', 'month', 'Compulsorily insured students in Germany (statutory student tariff), aged 23-29 without child, valid from 01.01.2026', 'Techniker Krankenkasse (TK), statutory health insurer', 'https://www.tk.de/en/contribution-foreign-students-german-health-insurance-2038022', 'from 23 years of age without child 110.38 EUR 35.91 EUR 146.29 EUR', 'VERIFIED', '2026-10-25', NULL, 'Same table as de-tk-student-health-2026-under23 (header: ''Monthly contributions for students with statutory insurance cover - valid from 01.01.2026''). Higher long-term care part (35.91) is the childless surcharge from age 23. Most Pakistani Master''s students will be 23+.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('de-tk-voluntary-student-health-2026', 'DE', 'cost', 'insurance', 'TK voluntary insurance minimum for students after student tariff ends (health part only)', 220.03, NULL, 'EUR', 'month', 'Students voluntarily insured with TK after student insurance expires (e.g. from age 30), with no income, 2026', 'Techniker Krankenkasse (TK), statutory health insurer', 'https://www.tk.de/en/contribution-foreign-students-german-health-insurance-2038022', 'If you have no income you pay the minimum contribution: Monthly contributions for voluntarily insured students Voluntarily insured students Health insurance* Long-term care insurance up to 23 years without child 220.03 EUR 47.46 EUR', 'VERIFIED', '2026-10-25', NULL, 'Health part only. Long-term care is extra: 47.46 EUR (under 23 / with child) or 55.37 EUR (23+ without child) per the same table. Relevant for PhD students aged 30+.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('de-stwm-basic-fee-ws2026', 'DE', 'cost', 'semester_fee', 'Studierendenwerk Muenchen Oberbayern basic fee (TUM semester fee), from summer 2026 onwards', 97, NULL, 'EUR', 'semester', 'Students at the 15 universities served by Studierendenwerk Muenchen Oberbayern (incl. TUM Munich/Garching/Weihenstephan), summer semester 2026 onwards, so covers winter semester 2026/27', 'Studierendenwerk Muenchen Oberbayern (Grundbeitragssatzung valid since 1 Oct 2025)', 'https://www.studierendenwerk-muenchen-oberbayern.de/en/about-us/studierendenwerk-bylaws/', 'There are currently 15 universities within our jurisdiction. From the summer semester 2026 onwards, the Basic Fee / Studierendenwerk Fee will amount to 97 euros.', 'VERIFIED', '2026-10-25', NULL, 'Same page: solidarity (MVV) fee ''suspended until further notice'' since WS 2023/24, so the basic fee is the whole semester fee for TUM''s Munich-area campuses. Matches TUM fees page (97.00 EUR, SS 2026); TUM''s own page still shows no separate WS 2026/27 figure. Straubing (82 EUR) and Heilbronn are outside this Studierendenwerk. English text; German version legally binding. The optional Deutschlandsemesterticket is not included.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('it-visa-fee-study-pkr-karachi-q4-2026', 'IT', 'cost', 'visa', 'Italian national study visa (D) fee in PKR, Oct-Dec 2026', 16250, NULL, 'PKR', 'once', 'National study visa (type D) applied for in the Consulate General Karachi jurisdiction (Karachi, Quetta BLS centres), October-December 2026', 'Consolato Generale d''Italia a Karachi (MAECI)', 'https://conskarachi.esteri.it/en/servizi-consolari-e-visti/servizi-per-il-cittadino-straniero/visti/quanto-costa-un-visto-e-come-pagare/', 'Consular fees vary every three months. From October to December 2026, the fees are as follows: ... National study visa (D) EUR 50,00 PKR 16,250 Payment may be made at the BLS centre where the application is submitted.', 'VERIFIED', '2026-10-25', NULL, 'EUR 50 = existing it-visa-fee-study. PKR amount is reset quarterly. The Islamabad Embassy page (see it-visa-fee-study-pkr-islamabad-q3-2026) had not yet posted Oct-Dec 2026 on 2026-10-25; Karachi''s Q4 PKR equals Islamabad''s Q3 PKR, so likely identical, but the Islamabad Q4 figure is unconfirmed. The ''...'' in the excerpt omits other visa types.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('it-visa-fee-study-pkr-islamabad-q3-2026', 'IT', 'cost', 'visa', 'Italian national study visa (D) fee in PKR, Islamabad, Jul-Sep 2026 (latest posted)', 16250, NULL, 'PKR', 'once', 'National study visa (type D) in the Embassy Islamabad jurisdiction (Islamabad, Lahore, Multan, Faisalabad BLS centres), July-September 2026; Oct-Dec 2026 not yet posted', 'Ambasciata d''Italia Islamabad (MAECI)', 'https://ambislamabad.esteri.it/en/servizi-consolari-e-visti/servizi-per-il-cittadino-straniero/visti/quanto-costa-un-visto-e-come-pagare/', 'From July to September 2026, the fees are as follows: ... National study visa (D) EUR 50,00 PKR 16,250 Payment may be made at the BLS centre where the application is submitted. Update to 24/06/2026', 'NEEDS_REVIEW', '2026-10-25', NULL, 'Period ended 30 Sep 2026; page not updated for Q4. Same page lists Apr-Jun 2026 as PKR 16,290. Use the Karachi Q4 item as the current reference until Islamabad updates.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('it-bls-service-fee-pakistan', 'IT', 'cost', 'visa', 'BLS-Intiana visa centre service fee (Italy, Pakistan)', 35, NULL, 'EUR', 'once', 'BLS-Intiana service fee stated by the Consulate Karachi for family reunification (EU citizens'' family) appointments at Karachi/Quetta; applicability to study visas not stated', 'Consolato Generale d''Italia a Karachi (MAECI)', 'https://conskarachi.esteri.it/en/servizi-consolari-e-visti/servizi-per-il-cittadino-straniero/visti/dove-chiedere-un-visto/', 'To increase the daily availability of appointments for applicants, appointments will be scheduled at the BLS-Intiana Visa Application Centres in Karachi and Quetta. The only fee payable is the BLS service fee of €35.', 'NEEDS_REVIEW', '2026-10-25', NULL, 'Only official statement of a BLS fee amount found. It sits in the family-reunification section (where the visa itself is free), so it is a strong hint but not confirmed for study visas. intianaitalyvisa.com returned 403 Forbidden in Chrome too. Same page confirms all visa applications go through VAC BLS-Intiana (Islamabad, Lahore, Multan, Faisalabad, Karachi, Quetta).');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('cn-csc-stipend-campuschina-bachelor', 'CN', 'cost', 'stipend', 'CSC scholarship living allowance, Bachelor''s (Campus China) - INCOME', 2500, NULL, 'CNY', 'month', 'Chinese Government Scholarship (full), undergraduate, current CSC admissions brochure (requires CSCA test, i.e. 2026+ cycle)', 'China Scholarship Council / Campus China (campuschina.org)', 'https://www.campuschina.org/zh/content/details1003_122933.html', '3.生活费： 本科生：2,500元人民币/月 硕士研究生和普通进修生：3,000元人民币/月 博士研究生和高级进修生：3,500元人民币/月', 'VERIFIED', '2026-10-25', NULL, 'INCOME. Official CSC page ''中国政府奖学金招生简章'' (undated; mentions the new CSCA undergraduate entrance test, so current cycle). Full scholarship also covers tuition, free dorm or accommodation subsidy, and insurance 800 CNY/person/year. Supersedes the older-cycle NEEDS_REVIEW figures from lxsy.nau.edu.cn (same amounts). Corroborated by NWPU''s CSC University Program page dated 2026-06-30 (3,000 Master''s / 3,500 PhD).');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('cn-csc-stipend-campuschina-master', 'CN', 'cost', 'stipend', 'CSC scholarship living allowance, Master''s (Campus China) - INCOME', 3000, NULL, 'CNY', 'month', 'Chinese Government Scholarship (full), Master''s students and general scholars, current CSC admissions brochure', 'China Scholarship Council / Campus China (campuschina.org)', 'https://www.campuschina.org/zh/content/details1003_122933.html', '硕士研究生和普通进修生：3,000元人民币/月', 'VERIFIED', '2026-10-25', NULL, 'INCOME. See cn-csc-stipend-campuschina-bachelor. NWPU (2026-06-30, for applications Nov 2026-Feb 2027): ''Master''s students/general scholars: CNY 3,000 per month''.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('cn-csc-stipend-campuschina-phd', 'CN', 'cost', 'stipend', 'CSC scholarship living allowance, PhD (Campus China) - INCOME', 3500, NULL, 'CNY', 'month', 'Chinese Government Scholarship (full), doctoral students and senior scholars, current CSC admissions brochure', 'China Scholarship Council / Campus China (campuschina.org)', 'https://www.campuschina.org/zh/content/details1003_122933.html', '博士研究生和高级进修生：3,500元人民币/月', 'VERIFIED', '2026-10-25', NULL, 'INCOME. See cn-csc-stipend-campuschina-bachelor.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('cn-cvasc-service-fee-regular', 'CN', 'cost', 'visa', 'Chinese Visa Application Service Center (Islamabad) service fee, regular', 13200, NULL, 'PKR', 'once', 'Visa applications at the Chinese Visa Application Service Center Islamabad (incl. X1 for Pakistani citizens), fee schedule from 1 June 2024, current page', 'Chinese Visa Application Service Center, Islamabad (visaforchina.cn, centre authorised by the Chinese Embassy)', 'https://www.visaforchina.cn/ISB4_EN/qianzhengyewu/jichuzhishi/feiyongbiaozhunjishixian', 'The new fee standards will be implemented from June 1st, 2024. ... Visa Application Service Fees Regular Service 13200 (Inclusive of GST) Express Service 19800 (Inclusive of GST)', 'VERIFIED', '2026-10-25', NULL, 'Unit PKR; cash only. Same table: visa fee for Pakistani citizens is 0 for all entry types (matches cn-x1-visa-fee-pakistan). Service fees are non-refundable. Optional Premium Lounge 13200 PKR. Page is the Islamabad centre; Lahore/Karachi centre fees not checked.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('cn-cvasc-service-fee-express', 'CN', 'cost', 'visa', 'Chinese Visa Application Service Center (Islamabad) service fee, express', 19800, NULL, 'PKR', 'once', 'Optional express processing at the Chinese Visa Application Service Center Islamabad, fee schedule from 1 June 2024', 'Chinese Visa Application Service Center, Islamabad (visaforchina.cn)', 'https://www.visaforchina.cn/ISB4_EN/qianzhengyewu/jichuzhishi/feiyongbiaozhunjishixian', 'Express Service 19800 (Inclusive of GST)', 'VERIFIED', '2026-10-25', NULL, 'Replaces (not adds to) the regular 13200 PKR service fee. Express: submit before 12 PM, collect after 12 PM on the expected date.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('cn-tsinghua-tuition-master-sci-eng-2027', 'CN', 'cost', 'tuition', 'Tsinghua Master''s tuition, Science/Engineering/Medicine (Chinese or bilingual)', 33000, NULL, 'CNY', 'year', 'Tsinghua international graduate students, Master''s in disciplines 07 Science, 08 Engineering, 10 Medicine taught in Chinese or bilingually, 2027 intake', 'Tsinghua University Graduate Admissions (yzbm.tsinghua.edu.cn)', 'https://yzbm.tsinghua.edu.cn/publish/s05/s0501/detail/bb745c8c-e817-4532-8cc1-70fa21bae1b5', '硕士 Master 07理学、08工学、10医学 07 Science,08 Engineering,10 Medicine 33,000 (每学年/Year)', 'VERIFIED', '2026-10-25', NULL, 'Page heading: ''2027年国际研究生学费列表 Tuition Fees of Graduate Programs for International Students 2027''. Economics/Management 30,000; Philosophy/Law/Education/Arts/History 28,000 per year. Many professional/English programmes are priced separately (see other Tsinghua items).');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('cn-tsinghua-tuition-master-english-eie-2027', 'CN', 'cost', 'tuition', 'Tsinghua English-taught Master of Engineering in Electronic Information', 39000, NULL, 'CNY', 'year', 'Tsinghua Department of Electronic Engineering, fully English-taught Master''s, 2027 intake', 'Tsinghua University Graduate Admissions (yzbm.tsinghua.edu.cn)', 'https://yzbm.tsinghua.edu.cn/publish/s05/s0501/detail/bb745c8c-e817-4532-8cc1-70fa21bae1b5', '电子工程系 Department of Electronic Engineering 电子信息全英文硕士学位项目 Master of Engineering in Electronic Information 39,000 (每学年/Year）', 'VERIFIED', '2026-10-25', NULL, 'Example of an English-taught engineering Master''s. Same list: Advanced Computing (CS) 39,000/year; Environment, Vehicle & Mobility, Global Manufacturing, IMEM, Nuclear 78,000 full programme (39,000 x 2); Materials 33,000/year; ICPM 228,000 full programme.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('cn-tsinghua-tuition-phd-sci-eng-2027', 'CN', 'cost', 'tuition', 'Tsinghua PhD tuition, Science/Engineering/Medicine', 40000, NULL, 'CNY', 'year', 'Tsinghua international doctoral students in 07 Science, 08 Engineering, 10 Medicine, 14 (IC science, intelligence science), Chinese or bilingual, 2027 intake', 'Tsinghua University Graduate Admissions (yzbm.tsinghua.edu.cn)', 'https://yzbm.tsinghua.edu.cn/publish/s05/s0501/detail/bb745c8c-e817-4532-8cc1-70fa21bae1b5', '博士 Doctor 07理学、08工学、10医学、14交叉学科（集成电路科学与工程、智能科学与技术） 07 Science,08 Engineering,10 Medicine,14 Integrated Circuit Science and Engineering,Intelligence Science and Technology 40,000 (每学年/Year)', 'VERIFIED', '2026-10-25', NULL, 'English-taught doctoral programmes listed (Environment, CS, Materials, SIGS) are also 40,000/year.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('cn-fudan-tuition-ug-uipe-2027', 'CN', 'cost', 'tuition', 'Fudan English-taught undergraduate Economics (UIPE), total programme tuition', 400000, NULL, 'CNY', 'once', 'Self-funded international undergraduates, Fudan School of Economics UIPE programme, intake 2027 onwards; total for the whole programme', 'Fudan University School of Economics (approved by Fudan President''s Office meeting)', 'https://econ.fudan.edu.cn/uipe/info/1026/1003.htm', '(本学费标准从2027级起执行starting with the intake of 2027) ... Undergraduate/Self-funded International Students 40万元/全部 400,000 yuan in total （最终以上海市教委备案为准）', 'VERIFIED', '2026-10-25', NULL, 'Unit ''once'' = whole programme, not per year (do not annualise without care; the page itself does not state a per-year split). Final figure ''subject to filing with Shanghai Municipal Education Commission''. Only one programme; Fudan''s general Chinese-taught tuition lists are PDFs (not readable in Chrome).');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('cn-fudan-accommodation-ayc', 'CN', 'cost', 'accommodation', 'Fudan international student dorm, AYC single room', 9000, NULL, 'CNY', 'semester', 'Fudan Handan campus, Asian Youth Center (AYC) single room, per academic term; page undated', 'Fudan University (official English site, Admission > Dorm)', 'https://www.fudan.edu.cn/en/Dorm/list.htm', 'AYC buildings Single 9000 RMB/per person/per academic term', 'NEEDS_REVIEW', '2026-10-25', NULL, 'Page footer ''© 2019 FUDAN UNIVERSITY''; no date on prices. Other rooms are priced per night (long term: main building single 120 / double 80; affiliated single 65; Fenglin single 90 / double 65 RMB per person per night) and were not stored because the planner has no ''day'' unit.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('cn-whu-tuition-ug-sci-eng', 'CN', 'cost', 'tuition', 'Wuhan University undergraduate tuition, Science & Engineering (Chinese medium)', 24000, NULL, 'CNY', 'year', 'Self-funded international undergraduates, Wuhan University, Science and Engineering, Chinese medium; fee page undated', 'Wuhan University School of International Education (admission.whu.edu.cn)', 'https://admission.whu.edu.cn/FRESHMEN_RELATED/FEES.htm', 'Tuition Fee Pay by Year Liberal Arts Science and Engineering Medicine /Stomatology Undergraduate student RMB 20,000 RMB24,000 RMB30,000 English Medium RMB23,000 English medium RMB28,000 English medium RMB40,000', 'NEEDS_REVIEW', '2026-10-25', NULL, 'Undated page. Table columns are Liberal Arts / Science and Engineering / Medicine. English-medium Science & Engineering undergraduate = 28,000. The 2026 admissions guide attaches ''Fee Standards for International Students at Wuhan University.doc'' (not opened: download).');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('cn-whu-tuition-master-sci-eng-chinese', 'CN', 'cost', 'tuition', 'Wuhan University Master''s tuition, Science & Engineering (Chinese medium)', 28000, NULL, 'CNY', 'year', 'Self-funded international Master''s students, Wuhan University, Science and Engineering, Chinese medium; fee page undated', 'Wuhan University School of International Education (admission.whu.edu.cn)', 'https://admission.whu.edu.cn/FRESHMEN_RELATED/FEES.htm', 'Master degree student RMB23,000 RMB28,000 RMB38,000 English medium RMB33,000 English medium RMB38,000 English medium RMB50,000', 'NEEDS_REVIEW', '2026-10-25', NULL, 'Columns Liberal Arts / Science and Engineering / Medicine. See cn-whu-tuition-master-sci-eng-english for English medium. Undated page.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('cn-whu-tuition-master-sci-eng-english', 'CN', 'cost', 'tuition', 'Wuhan University Master''s tuition, Science & Engineering (English medium)', 38000, NULL, 'CNY', 'year', 'Self-funded international Master''s students, Wuhan University, Science and Engineering, English medium; fee page undated', 'Wuhan University School of International Education (admission.whu.edu.cn)', 'https://admission.whu.edu.cn/FRESHMEN_RELATED/FEES.htm', 'Master degree student RMB23,000 RMB28,000 RMB38,000 English medium RMB33,000 English medium RMB38,000 English medium RMB50,000', 'NEEDS_REVIEW', '2026-10-25', NULL, 'English medium row: Liberal Arts 33,000 / Science and Engineering 38,000 / Medicine 50,000. PhD (same page): Chinese 30,000/40,000/45,000; English 36,000/46,000/55,000. Undated page.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('cn-whu-accommodation', 'CN', 'cost', 'accommodation', 'Wuhan University international student dorms (range)', 6900, 16000, 'CNY', 'year', 'Wuhan University on-campus international dorms, Campus of Humanities and Science (twin-room flat to single with balcony); page undated', 'Wuhan University School of International Education (admission.whu.edu.cn)', 'https://admission.whu.edu.cn/FRESHMEN_RELATED/ACCOMMODATION.htm', 'No.6 Building A flat wih 2 twin rooms 6900 3700 800 50 ... No.3 Building Single room ... With Balcony 16000 8500 1800 80', 'NEEDS_REVIEW', '2026-10-25', NULL, 'Columns are RMB/year, RMB/semester, RMB/month, RMB/day. Single rooms 13,000-14,000/year; Medicine campus twin rooms 9,500-9,600/year. Electricity extra at RMB 0.6/kWh; no bedding provided. Undated page.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('cn-whu-living-estimate', 'CN', 'cost', 'living', 'Wuhan University living expenses estimate', 1000, 2000, 'CNY', 'month', 'International students in Wuhan, WHU fee page (undated)', 'Wuhan University School of International Education (admission.whu.edu.cn)', 'https://admission.whu.edu.cn/FRESHMEN_RELATED/FEES.htm', 'Living Expenses RMB1,000-2,000 per month', 'OFFICIAL_ESTIMATE', '2026-10-25', NULL, 'Same page: insurance RMB 1,000 per year; physical examination around RMB 300; residence permit RMB 400 (within a year) / 800 (2-3 years) / 1,000 (more than 3 years); textbooks RMB 200-1000 per year. Undated, may be low for 2026.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('cn-whu-proof-of-funds', 'CN', 'proof_of_funds', 'living', 'Minimum bank statement for Wuhan University graduate applicants', 5000, NULL, 'USD', 'once', 'International applicants to Wuhan University Master''s and Doctoral degrees, 2026 admissions guide (autumn 2026 intake)', 'Wuhan University School of International Education (admission.whu.edu.cn)', 'https://admission.whu.edu.cn/info/1131/5822.htm', 'Financial certification/bank statement (minimum US$ 5,000)', 'VERIFIED', '2026-10-25', '["financial certification","bank statement"]', 'Guide published 2025-11-18 for degree programmes starting autumn 2026; the 2024 and 2025 guides state the same minimum. A university admission requirement, not a Chinese visa rule. Same guide: application fee RMB 800/US$111.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('it-unipd-dsu-nonres-isee-low', 'IT', 'cost', 'stipend', 'Padova/ESU regional scholarship, full-time non-resident, ISEE < 13,153.12 (income)', 8246, NULL, 'EUR', 'year', 'Univ. of Padova regional DSU call a.y. 2026/27, full-time non-resident (fuori sede)', 'University of Padova / ESU Padova (Veneto Region)', 'https://wwwassets.unipd.it/sites/default/files/2026-07/1.Bando%20Borse%20Studio%202026-27_ENG_0.pdf', 'Scholarship amount for ISEE of less than 13,153.12 ... Non-resident Commuter 8,246.00', 'VERIFIED', '2026-10-25', NULL, 'Scholarship = income, not a cost. Table columns read by order and cross-checked: 7,171.11 x 1.15 uplift (DM 1320/2021) ≈ 8,246; minimum = half of 7,171.11.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('it-unipd-dsu-nonres-isee-mid', 'IT', 'cost', 'stipend', 'Padova/ESU regional scholarship, full-time non-resident, ISEE 13,153.12–17,537.50 (income)', 7171.11, NULL, 'EUR', 'year', 'Univ. of Padova regional DSU call a.y. 2026/27, full-time non-resident', 'University of Padova / ESU Padova (Veneto Region)', 'https://wwwassets.unipd.it/sites/default/files/2026-07/1.Bando%20Borse%20Studio%202026-27_ENG_0.pdf', 'Scholarship amount for ISEE of between 13,153.12 and 17,537.50 ... 7,171.11', 'VERIFIED', '2026-10-25', NULL, 'Income, not a cost.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('it-unipd-dsu-nonres-min', 'IT', 'cost', 'stipend', 'Padova/ESU regional scholarship, full-time non-resident, minimum (ISEE > 17,537.50) (income)', 3585.5, NULL, 'EUR', 'year', 'Univ. of Padova regional DSU call a.y. 2026/27, full-time non-resident', 'University of Padova / ESU Padova (Veneto Region)', 'https://wwwassets.unipd.it/sites/default/files/2026-07/1.Bando%20Borse%20Studio%202026-27_ENG_0.pdf', 'Minimum scholarship amount for an ISEE above 17,537.50 (gradually reduced to) ... 3,585.50', 'VERIFIED', '2026-10-25', NULL, 'Income, not a cost.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('it-esu-padova-residence-fee', 'IT', 'cost', 'accommodation', 'ESU Padova residence fee for scholarship holders (deducted from grant)', 1600, NULL, 'EUR', 'year', 'Non-resident regional scholarship holders using ESU residences, a.y. 2026/27', 'University of Padova / ESU Padova (Veneto Region)', 'https://wwwassets.unipd.it/sites/default/files/2026-07/1.Bando%20Borse%20Studio%202026-27_ENG_0.pdf', 'A fee of 1,600.00, corresponding to the standard fee due for the accommodation service, and a fee of 760.00, corresponding to the catering service (one meal per day), is deducted from the non-resident students who use the residential facilities of the ESU of Padua.', 'VERIFIED', '2026-10-25', NULL, 'Only for grant holders housed by ESU; 760 EUR catering also deducted.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('it-polimi-dsu-fuorisede-band1', 'IT', 'cost', 'stipend', 'Polimi DSU scholarship, fuori sede in private housing, 1st income band (income)', 8248, NULL, 'EUR', 'year', 'Politecnico di Milano DSU a.y. 2026/27 (Lombardy), fuori sede not in Polimi housing, ISEE up to 13,443.97', 'Politecnico di Milano (Lombardy Region DSU)', 'https://www.polimi.it/fileadmin/user_upload/studenti/tasse-borse-agevolazioni-economiche/dsu/bando_2026-2027/Bando_integrativo_DSU_aa_26_27_.pdf', 'Studente Fuori Sede alloggiato presso altre strutture abitative, pubbliche o private 1ª fascia 7.419,00 + un pasto giornaliero gratuito per un totale di 8.248,00;', 'VERIFIED', '2026-10-25', NULL, 'Income, not a cost. 7,419 cash + free daily meal.');
