INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('it-polimi-residence-grant-deduction', 'IT', 'cost', 'accommodation', 'Polimi residence cost for DSU grant holders (deducted from grant)', 2847, NULL, 'EUR', 'year', 'DSU grant holders housed in Politecnico residences, a.y. 2026/27', 'Politecnico di Milano', 'https://www.polimi.it/fileadmin/user_upload/studenti/tasse-borse-agevolazioni-economiche/dsu/bando_2026-2027/Bando_integrativo_DSU_aa_26_27_.pdf', 'agli studenti assegnatari alloggiati presso le strutture abitative del Politecnico verrà effettuata una trattenuta sull''importo della borsa di studio pari a 2.847,00.', 'VERIFIED', '2026-10-25', NULL, 'Deducted from the grant, not paid separately.');
